// Pixel Office — the Boss in the browser (F4-3a, docs/F43_TASARIM.md). Same protocol as the connector's BossDesk
// (pixel_connector/boss.py): the plan schema, the reply parsing and the prompts are ported line by line and checked
// against the connector's own outcomes (tests/boss_plan_vectors.json, generated by tests/_boss_shared.py), and the
// limits, roles and texts come from the generated boss_rules.js. Everything a model writes is untrusted.

import { BOSS_RULES as R } from './boss_rules.js';

export class BossError extends Error {
  constructor(code, detail) { super(detail); this.code = code; this.detail = detail; }
}

// -- strict JSON (as Python's json.loads with duplicate-key and constant hooks) -------------------------------------
/** A JSON number written with a fraction or exponent: Python keeps it a float, so `"v": 1.0` is not the int 1. */
export class JsonFloat {
  constructor(value) { this.value = value; }
}

/** RFC 8259 JSON → JS values; duplicate keys, NaN/Infinity and trailing data are errors; floats become JsonFloat. */
export function parseJsonStrict(text) {
  let i = 0;
  const fail = () => { throw new SyntaxError('json'); };
  const ws = () => { while (i < text.length && ' \t\n\r'.includes(text[i])) i++; };
  const str = () => {
    let out = '';
    i++;
    for (;;) {
      if (i >= text.length) fail();
      const c = text[i];
      if (c === '"') { i++; return out; }
      if (c < ' ') fail();
      if (c === '\\') {
        const e = text[i + 1];
        const map = { '"': '"', '\\': '\\', '/': '/', b: '\b', f: '\f', n: '\n', r: '\r', t: '\t' };
        if (e === 'u') {
          const h = text.slice(i + 2, i + 6);
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail();
          out += String.fromCharCode(parseInt(h, 16));
          i += 6;
        } else if (Object.hasOwn(map, e)) { out += map[e]; i += 2; } else fail();
      } else { out += c; i++; }
    }
  };
  const num = () => {
    const m = /^-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?/.exec(text.slice(i));
    if (!m) fail();
    i += m[0].length;
    const v = Number(m[0]);
    return m[2] || m[3] ? new JsonFloat(v) : v;
  };
  const value = (depth) => {
    if (depth > 200) fail();
    ws();
    const c = text[i];
    if (c === '{') {
      i++;
      const obj = {};
      const seen = new Set();
      ws();
      if (text[i] === '}') { i++; return obj; }
      for (;;) {
        ws();
        if (text[i] !== '"') fail();
        const k = str();
        if (seen.has(k)) fail();
        seen.add(k);
        ws();
        if (text[i] !== ':') fail();
        i++;
        Object.defineProperty(obj, k, { value: value(depth + 1), enumerable: true, writable: true, configurable: true });
        ws();
        if (text[i] === ',') { i++; continue; }
        if (text[i] === '}') { i++; return obj; }
        fail();
      }
    }
    if (c === '[') {
      i++;
      const arr = [];
      ws();
      if (text[i] === ']') { i++; return arr; }
      for (;;) {
        arr.push(value(depth + 1));
        ws();
        if (text[i] === ',') { i++; continue; }
        if (text[i] === ']') { i++; return arr; }
        fail();
      }
    }
    if (c === '"') return str();
    if (text.startsWith('true', i)) { i += 4; return true; }
    if (text.startsWith('false', i)) { i += 5; return false; }
    if (text.startsWith('null', i)) { i += 4; return null; }
    return num();
  };
  const v = value(0);
  ws();
  if (i !== text.length) fail();
  return v;
}

// -- text checks (workflows._hidden_char / _text, boss._strict_text) -------------------------------------------------
const HIDDEN = /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/u;
const bytes = (s) => new TextEncoder().encode(s).length;
const chars = (s) => [...s].length;                       // Python len(): code points, not UTF-16 units
const isPlain = (o) => o !== null && typeof o === 'object' && !Array.isArray(o) && !(o instanceof JsonFloat);

function hiddenIn(s, allowNewlines) {
  for (const ch of s) {
    if (allowNewlines && (ch === '\n' || ch === '\t')) continue;
    if (HIDDEN.test(ch)) return true;
  }
  return false;
}

function strictText(raw, where, maxLen, allowNewlines = false, maxBytes = null) {
  if (typeof raw === 'string' && hiddenIn(raw, allowNewlines)) throw new BossError('bad_plan', where);
  if (typeof raw !== 'string') throw new BossError('bad_plan', where);
  const s = raw.trim();
  if (!s || chars(s) > maxLen || hiddenIn(s, allowNewlines)) throw new BossError('bad_plan', where);
  if (maxBytes !== null && bytes(s) > maxBytes) throw new BossError('bad_plan', where);
  return s;
}

function allowed(raw, fields, where) {
  if (!isPlain(raw) || !Object.keys(raw).every((k) => fields.includes(k))) throw new BossError('bad_plan', where);
}

const PLAN_FIELDS = ['v', 'summary', 'orders'];
const ORDER_FIELDS = ['id', 'role', 'title', 'goal', 'accept', 'files', 'after'];
const ORDER_REQUIRED = ['id', 'role', 'title', 'goal', 'accept'];
const ORDER_ID_RE = /^o[1-9]$/;

function filePattern(raw, where) {
  if (typeof raw !== 'string' || chars(raw) < 1 || chars(raw) > R.fileMax || raw !== raw.trim()) {
    throw new BossError('bad_plan', where);
  }
  if ([...raw].some((ch) => hiddenIn(ch, false) || R.fileBadChars.includes(ch)) || raw.startsWith('/')) {
    throw new BossError('bad_plan', where);
  }
  if (raw.split('/').some((p) => p === '' || p === '.' || p === '..')) throw new BossError('bad_plan', where);
  return raw;
}

function textList(raw, where, maxItems, minItems, item) {
  if (!Array.isArray(raw) || raw.length < minItems || raw.length > maxItems) throw new BossError('bad_plan', where);
  return raw.map((x, i) => item(x, `${where}[${i}]`));
}

function after(raw, where, earlier) {
  if (!Array.isArray(raw) || new Set(raw.map((x) => JSON.stringify(x))).size !== raw.length) {
    throw new BossError('bad_plan', where);
  }
  raw.forEach((oid, i) => {
    if (typeof oid !== 'string' || !earlier.includes(oid)) throw new BossError('bad_plan', `${where}[${i}]`);
  });
  return [...raw];
}

export function orderPrompt(summary, order) {
  const files = order.files.map((f) => `- ${f}`).join('\n') || R.text.filesNone;
  const accept = order.accept.map((a) => `- ${a}`).join('\n');
  return [R.text.orderHead, R.roles[order.role].instruction, `Planın özeti: ${summary}`, `İş emri: ${order.title}`,
    `Hedef:\n${order.goal}`, `Kabul ölçütleri:\n${accept}`, `Dokunulacak dosyalar:\n${files}`, R.text.orderRules]
    .join('\n\n');
}

function validateOrder(raw, where, earlier, summary, enabledProfiles, roles) {
  allowed(raw, ORDER_FIELDS, where);
  if (!ORDER_REQUIRED.every((k) => Object.hasOwn(raw, k))) throw new BossError('bad_plan', `${where}: missing field`);
  const oid = raw.id;
  if (typeof oid !== 'string' || !ORDER_ID_RE.test(oid) || earlier.includes(oid)) throw new BossError('bad_plan', `${where}.id`);
  const role = raw.role;
  if (typeof role !== 'string' || !roles.includes(role)) throw new BossError('bad_plan', `${where}.role`);
  const out = {
    id: oid, role,
    title: strictText(raw.title, `${where}.title`, R.titleMax),
    goal: strictText(raw.goal, `${where}.goal`, R.goalMaxBytes, true, R.goalMaxBytes),
    accept: textList(raw.accept, `${where}.accept`, R.acceptMaxItems, 1, (x, w) => strictText(x, w, R.acceptMax)),
    files: textList(Object.hasOwn(raw, 'files') ? raw.files : [], `${where}.files`, R.filesMaxItems, 0, filePattern),
    after: after(Object.hasOwn(raw, 'after') ? raw.after : [], `${where}.after`, earlier),
  };
  if (bytes(orderPrompt(summary, out)) > R.promptMax) {
    throw new BossError('bad_plan', `${where}: the order is too long for one step instruction`);
  }
  if (!enabledProfiles.includes(R.roles[role].profile)) throw new BossError('role_unavailable', `${where}.role`);
  return out;
}

export function departmentRoles(department = R.defaultDepartment) {
  const d = R.departments.find((x) => x.id === department);
  if (!d) throw new BossError('bad_request', 'department');
  return d.roles;
}

/** The Boss's plan → normalized copy, or BossError(bad_plan | role_unavailable) — boss.validate_plan. */
export function validatePlan(raw, { enabledProfiles = ['readonly', 'edit', 'dev'], fixRound = false,
  department = R.defaultDepartment } = {}) {
  const roles = departmentRoles(department);
  allowed(raw, PLAN_FIELDS, 'plan');
  if (!PLAN_FIELDS.every((k) => Object.hasOwn(raw, k))) throw new BossError('bad_plan', 'plan: missing field');
  if (typeof raw.v !== 'number' || !Number.isInteger(raw.v) || raw.v !== R.planVersion) throw new BossError('bad_plan', 'v');
  const summary = strictText(raw.summary, 'summary', R.summaryMax);
  const limit = fixRound ? R.maxFixOrders : R.maxOrders;
  if (!Array.isArray(raw.orders) || raw.orders.length < 1 || raw.orders.length > limit) throw new BossError('bad_plan', 'orders');
  const orders = [];
  raw.orders.forEach((o, i) => {
    orders.push(validateOrder(o, `orders[${i}]`, orders.map((x) => x.id), summary, enabledProfiles, roles));
  });
  return { v: R.planVersion, summary, orders };
}

// -- the reply's JSON block (boss._json_block) ----------------------------------------------------------------------
function count(hay, needle) { return hay.split(needle).length - 1; }

function stripFence(body) {
  const lines = body.split('\n');
  if (lines.length >= 2 && ['```', '```json'].includes(lines[0].trim()) && lines[lines.length - 1].trim() === '```') {
    return lines.slice(1, -1).join('\n').trim();
  }
  return body;
}

export function jsonBlock(output, start, end) {
  if (typeof output !== 'string' || !output.trim() || bytes(output) > R.resultMax) throw new BossError('bad_plan', 'output');
  if (count(output, start) !== 1 || count(output, end) !== 1) throw new BossError('bad_plan', 'block');
  const rest = output.slice(output.indexOf(start) + start.length);
  if (!rest.includes(end)) throw new BossError('bad_plan', 'block');
  const body = stripFence(rest.slice(0, rest.indexOf(end)).trim());
  if (bytes(body) > R.planJsonMax) throw new BossError('bad_plan', 'size');
  try {
    return parseJsonStrict(body);
  } catch {
    throw new BossError('bad_plan', 'json');
  }
}

const fmt = (tpl, ...args) => { let k = 0; return tpl.replace(/%[sd]/g, () => String(args[k++])); };
export const planMarkers = (nonce) => [fmt(R.text.planMark, nonce, 'BAŞLANGIÇ'), fmt(R.text.planMark, nonce, 'SON')];
export const reviewMarkers = (nonce) => [fmt(R.text.reviewMark, nonce, 'BAŞLANGIÇ'), fmt(R.text.reviewMark, nonce, 'SON')];

export function extractPlan(output, nonce, options = {}) {
  const raw = jsonBlock(output, ...planMarkers(nonce));
  if (!isPlain(raw)) throw new BossError('bad_plan', 'json');
  return validatePlan(raw, options);
}

// -- prompts (boss.planning_prompt / retry_prompt / review_prompt) ---------------------------------------------------
function rolesText(department) {
  return `Roller:\n${departmentRoles(department).map((rid) => {
    const r = R.roles[rid];
    return `- ${r.id} (${r.name}, ${R.profileText[r.profile]}): ${r.instruction}`;
  }).join('\n')}`;
}

export function planningPrompt(brief, nonce, department = R.defaultDepartment) {
  const [s, e] = planMarkers(nonce);
  return [R.text.planHead, R.boss.instruction, R.text.planRules, rolesText(department), R.text.planSchema,
    fmt(R.text.planOutput, s, e), `${R.text.planBriefHead}\n${brief}`].join('\n\n');
}

export function retryPrompt(reason, nonce) {
  const [s, e] = planMarkers(nonce);
  return fmt(R.text.retryPrompt, Object.hasOwn(R.extractReasons, reason) ? R.extractReasons[reason] : `alan ${reason}`, s, e);
}

export function reviewPrompt(plan, nonce, fixAllowed, department = R.defaultDepartment) {
  const orders = plan.orders.map((o) => `${o.id} (${R.roles[o.role].name}): ${o.title}\nKabul ölçütleri:\n`
    + o.accept.map((a) => `- ${a}`).join('\n')).join('\n\n');
  const [s, e] = reviewMarkers(nonce);
  const parts = [R.text.reviewHead, R.text.reviewPrompt, `Planın özeti: ${plan.summary}`, `İş emirleri:\n${orders}`];
  if (fixAllowed) parts.push(rolesText(department), R.text.planSchema, R.text.reviewFix);
  else parts.push(R.text.reviewNoFix);
  parts.push(fmt(R.text.reviewReport, s, e));
  return parts.join('\n\n');
}

/** The Boss's review reply → {decision, plan, text, note}; never throws (unreadable = no fix round). */
export function parseReview(output, nonce, options = {}) {
  const text = typeof output === 'string' ? output : '';
  const [s, e] = reviewMarkers(nonce);
  const head = text.split(s)[0].trim();
  const out = { decision: null, plan: null, text: head, note: 'review_unreadable' };
  let raw;
  try { raw = jsonBlock(text, s, e); } catch { return out; }
  if (!isPlain(raw) || !Object.keys(raw).every((k) => ['v', 'decision', 'plan'].includes(k))
      || typeof raw.v !== 'number' || !Number.isInteger(raw.v) || raw.v !== R.planVersion
      || !['accept', 'fix'].includes(raw.decision) || (raw.decision === 'accept') !== !Object.hasOwn(raw, 'plan')) {
    return out;
  }
  out.decision = raw.decision;
  out.note = null;
  if (raw.decision === 'fix') {
    try { out.plan = validatePlan(raw.plan, { ...options, fixRound: true }); } catch { out.note = 'fix_invalid'; }
  }
  return out;
}
